arguments.command:
python3 -c "
import zipfile
p='/root/event_announcement_template.hwpx'
with zipfile.ZipFile(p,'r') as z:
    for name in z.namelist():
        try:
            data=z.read(name).decode('utf-8')
            if '{{' in data:
                print('===', name, '===')
                for i,line in enumerate(data.split('\n')):
                    if '{{' in line:
                        print(f'  Line {i}: {line[:300]}')
        except Exception as e:
            pass
"

