    for name in z.namelist():
        print(f'  {name}')
        try:
            data = z.read(name).decode('utf-8')
            if '{{' in data:
                print(f'    WARNING: placeholder found in {name}')
                found_placeholder = True
        except:
            pass
if found_placeholder:
    print('FAIL: placeholders remain')
